    val CODES = listOf("system", "en", "ru", "es", "pt", "fr", "de", "ar", "hi", "tr", "zh")
    val NAMES = mapOf("en" to "English", "ru" to "Русский", "es" to "Español", "pt" to "Português", "fr" to "Français", "de" to "Deutsch", "ar" to "العربية", "hi" to "हिन्दी", "tr" to "Türkçe", "zh" to "中文")
    val RTL = setOf("ar")

    private var lang = "en"

    fun isRtl() = lang in RTL

    /** Определить язык из настроек; "system" → язык телефона, если поддержан, иначе английский. */
    fun apply(ctx: Context) {
        val chosen = Settings.language(ctx)
        lang = if (chosen == "system") {
            val dev = Locale.getDefault().language
            if (dev in listOf("en", "ru", "es", "pt", "fr", "de", "ar", "hi", "tr", "zh")) dev else "en"
        } else if (chosen in listOf("en", "ru", "es", "pt", "fr", "de", "ar", "hi", "tr", "zh")) chosen else "en"
    }

    private val idx = mapOf("en" to 0, "ru" to 1, "es" to 2, "pt" to 3, "fr" to 4, "de" to 5, "ar" to 6, "hi" to 7, "tr" to 8, "zh" to 9)

    fun t(key: String, vararg args: Any?): String {
        val row = M[key] ?: return key
        val s = row.getOrNull(idx[lang] ?: 0) ?: row[0]
        return if (args.isEmpty()) s else String.format(s, *args)
    }

